PRAGMA foreign_keys = ON;

-- 1. Schema Teardown (Children Before Parents)
DROP TABLE IF EXISTS anomaly_records;
DROP TABLE IF EXISTS attributions;
DROP TABLE IF EXISTS communication_events;
DROP TABLE IF EXISTS send_attempts;
DROP TABLE IF EXISTS order_lines;
DROP TABLE IF EXISTS orders;
DROP TABLE IF EXISTS cart_lines;
DROP TABLE IF EXISTS carts;
DROP TABLE IF EXISTS sessions;
DROP TABLE IF EXISTS consents;
DROP TABLE IF EXISTS customers;
DROP TABLE IF EXISTS message_templates;
DROP TABLE IF EXISTS campaigns;
DROP TABLE IF EXISTS products;

-- 2. Schema DDL (Parents Before Children)
CREATE TABLE products (
	product_id VARCHAR(32) NOT NULL, 
	sku VARCHAR(64) NOT NULL, 
	name VARCHAR(128) NOT NULL, 
	category VARCHAR(64) NOT NULL, 
	price NUMERIC(10, 2) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	PRIMARY KEY (product_id)
);
CREATE TABLE campaigns (
	campaign_id VARCHAR(32) NOT NULL, 
	name VARCHAR(128) NOT NULL, 
	channel VARCHAR(16) NOT NULL, 
	trigger_delay_minutes INTEGER NOT NULL, 
	discount_percent NUMERIC(5, 2) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	created_at DATETIME, 
	PRIMARY KEY (campaign_id)
);
CREATE TABLE message_templates (
	template_id VARCHAR(32) NOT NULL, 
	campaign_id VARCHAR(32) NOT NULL, 
	channel VARCHAR(16) NOT NULL, 
	variant VARCHAR(8) NOT NULL, 
	subject VARCHAR(255), 
	body_template VARCHAR(1024) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	PRIMARY KEY (template_id), 
	FOREIGN KEY(campaign_id) REFERENCES campaigns (campaign_id) ON DELETE CASCADE
);
CREATE TABLE customers (
	customer_id VARCHAR(32) NOT NULL, 
	first_name VARCHAR(64) NOT NULL, 
	last_name VARCHAR(64) NOT NULL, 
	email VARCHAR(128) NOT NULL, 
	phone VARCHAR(32) NOT NULL, 
	preferred_channel VARCHAR(16) NOT NULL, 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (customer_id)
);
CREATE TABLE consents (
	consent_id VARCHAR(32) NOT NULL, 
	customer_id VARCHAR(32) NOT NULL, 
	channel VARCHAR(16) NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	effective_at DATETIME NOT NULL, 
	source VARCHAR(64) NOT NULL, 
	created_at DATETIME, 
	PRIMARY KEY (consent_id), 
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id) ON DELETE CASCADE
);
CREATE TABLE sessions (
	session_id VARCHAR(32) NOT NULL, 
	customer_id VARCHAR(32) NOT NULL, 
	device_type VARCHAR(32) NOT NULL, 
	ip_address VARCHAR(45), 
	user_agent VARCHAR(255), 
	started_at DATETIME NOT NULL, 
	ended_at DATETIME, 
	PRIMARY KEY (session_id), 
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id) ON DELETE CASCADE
);
CREATE TABLE carts (
	cart_id VARCHAR(32) NOT NULL, 
	customer_id VARCHAR(32) NOT NULL, 
	session_id VARCHAR(32), 
	status VARCHAR(32) NOT NULL, 
	subtotal NUMERIC(10, 2) NOT NULL, 
	discount_total NUMERIC(10, 2) NOT NULL, 
	total_amount NUMERIC(10, 2) NOT NULL, 
	created_at DATETIME, 
	updated_at DATETIME, 
	last_activity_at DATETIME NOT NULL, 
	abandoned_at DATETIME, 
	recovered_at DATETIME, 
	PRIMARY KEY (cart_id), 
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id) ON DELETE CASCADE, 
	FOREIGN KEY(session_id) REFERENCES sessions (session_id) ON DELETE SET NULL
);
CREATE TABLE cart_lines (
	cart_line_id VARCHAR(48) NOT NULL, 
	cart_id VARCHAR(32) NOT NULL, 
	product_id VARCHAR(32) NOT NULL, 
	quantity INTEGER NOT NULL, 
	unit_price NUMERIC(10, 2) NOT NULL, 
	total_price NUMERIC(10, 2) NOT NULL, 
	PRIMARY KEY (cart_line_id), 
	FOREIGN KEY(cart_id) REFERENCES carts (cart_id) ON DELETE CASCADE, 
	FOREIGN KEY(product_id) REFERENCES products (product_id) ON DELETE RESTRICT
);
CREATE TABLE orders (
	order_id VARCHAR(32) NOT NULL, 
	customer_id VARCHAR(32) NOT NULL, 
	cart_id VARCHAR(32), 
	total_amount NUMERIC(10, 2) NOT NULL, 
	order_timestamp DATETIME NOT NULL, 
	status VARCHAR(32) NOT NULL, 
	PRIMARY KEY (order_id), 
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id) ON DELETE CASCADE, 
	FOREIGN KEY(cart_id) REFERENCES carts (cart_id) ON DELETE SET NULL
);
CREATE TABLE order_lines (
	order_line_id VARCHAR(48) NOT NULL, 
	order_id VARCHAR(32) NOT NULL, 
	product_id VARCHAR(32) NOT NULL, 
	quantity INTEGER NOT NULL, 
	unit_price NUMERIC(10, 2) NOT NULL, 
	total_price NUMERIC(10, 2) NOT NULL, 
	PRIMARY KEY (order_line_id), 
	FOREIGN KEY(order_id) REFERENCES orders (order_id) ON DELETE CASCADE, 
	FOREIGN KEY(product_id) REFERENCES products (product_id) ON DELETE RESTRICT
);
CREATE TABLE send_attempts (
	send_id VARCHAR(32) NOT NULL, 
	message_id VARCHAR(64) NOT NULL, 
	campaign_id VARCHAR(32) NOT NULL, 
	template_id VARCHAR(32), 
	cart_id VARCHAR(32) NOT NULL, 
	customer_id VARCHAR(32) NOT NULL, 
	channel VARCHAR(16) NOT NULL, 
	status VARCHAR(32) NOT NULL, 
	suppression_reason VARCHAR(64), 
	scheduled_at DATETIME NOT NULL, 
	sent_at DATETIME, 
	created_at DATETIME, 
	PRIMARY KEY (send_id), 
	FOREIGN KEY(campaign_id) REFERENCES campaigns (campaign_id) ON DELETE CASCADE, 
	FOREIGN KEY(template_id) REFERENCES message_templates (template_id) ON DELETE SET NULL, 
	FOREIGN KEY(cart_id) REFERENCES carts (cart_id) ON DELETE CASCADE, 
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id) ON DELETE CASCADE
);
CREATE TABLE communication_events (
	event_id VARCHAR(32) NOT NULL, 
	send_id VARCHAR(32) NOT NULL, 
	event_type VARCHAR(32) NOT NULL, 
	timestamp DATETIME NOT NULL, 
	metadata_json TEXT, 
	PRIMARY KEY (event_id), 
	FOREIGN KEY(send_id) REFERENCES send_attempts (send_id) ON DELETE CASCADE
);
CREATE TABLE attributions (
	attribution_id VARCHAR(32) NOT NULL, 
	order_id VARCHAR(32) NOT NULL, 
	send_id VARCHAR(32) NOT NULL, 
	campaign_id VARCHAR(32) NOT NULL, 
	cart_id VARCHAR(32), 
	order_timestamp DATETIME NOT NULL, 
	qualifying_click_at DATETIME NOT NULL, 
	latency_hours INTEGER NOT NULL, 
	attributed_revenue NUMERIC(10, 2) NOT NULL, 
	model VARCHAR(32) NOT NULL, 
	created_at DATETIME, 
	PRIMARY KEY (attribution_id), 
	FOREIGN KEY(order_id) REFERENCES orders (order_id) ON DELETE CASCADE, 
	FOREIGN KEY(send_id) REFERENCES send_attempts (send_id) ON DELETE CASCADE, 
	FOREIGN KEY(campaign_id) REFERENCES campaigns (campaign_id) ON DELETE CASCADE, 
	FOREIGN KEY(cart_id) REFERENCES carts (cart_id) ON DELETE SET NULL
);
CREATE TABLE anomaly_records (
	anomaly_id VARCHAR(32) NOT NULL, 
	issue_type VARCHAR(64) NOT NULL, 
	affected_entity VARCHAR(64) NOT NULL, 
	affected_record_id VARCHAR(64) NOT NULL, 
	detected_at DATETIME, 
	observed_value TEXT NOT NULL, 
	expected_value TEXT NOT NULL, 
	ground_truth_label VARCHAR(64) NOT NULL, 
	expected_decision VARCHAR(128) NOT NULL, 
	actual_decision VARCHAR(128) NOT NULL, 
	resolution_status VARCHAR(32) NOT NULL, 
	PRIMARY KEY (anomaly_id)
);

